import ProblemDetails from "../models/ProblemDetails";

export default interface ApiResponse<T = unknown> {
  success: boolean;
  data?: T;
  errorMessage?: string;
  statusCode?: number;
  /** Server identity of the terminal HTTP attempt, never generated by this client. */
  requestId?: string;
  /** Distributed identity supplied by the server, when available. */
  traceId?: string;
  /** Distinguishes transport and contract failures from an HTTP error response. */
  failureKind?: "http" | "transport" | "contract" | "cancelled";
  /** Header takes precedence when an incompatible server sends two different IDs. */
  requestIdMismatch?: boolean;
  /** Structured error details supplied by the API, when the failed response uses that schema. */
  problemDetails?: ProblemDetails;
}
